-- Metadata only. Run with psql -X -qAt -v ON_ERROR_STOP=1 -f export.sql.
-- The caller selects an already authorized connection; no connection discovery.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog;
WITH rel AS (SELECT c.* FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('auth','public') AND c.relkind IN ('r','p','v','m','f')),
relids AS (SELECT c.oid,n.nspname||'.'||c.relname id FROM rel c JOIN pg_namespace n ON n.oid=c.relnamespace),
funcs AS (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('auth','public') AND p.prokind IN ('f','p')),
"types" AS (SELECT n.nspname||'.'||t.typname id,pg_get_userbyid(t.typowner) owner,t.typacl::text acl,jsonb_build_object('kind',t.typtype,'base',format_type(t.typbasetype,t.typtypmod),'notNull',t.typnotnull,'default',t.typdefault,'labels',ARRAY(SELECT e.enumlabel::text FROM pg_enum e WHERE e.enumtypid=t.oid ORDER BY e.enumsortorder),'constraints',ARRAY(SELECT pg_get_constraintdef(c.oid,false) FROM pg_constraint c WHERE c.contypid=t.oid ORDER BY c.conname))::text definition FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN ('auth','public') AND t.typtype IN ('e','d')),
"sequences" AS (SELECT n.nspname||'.'||c.relname id,pg_get_userbyid(c.relowner) owner,c.relacl::text acl,jsonb_build_object('type',format_type(s.seqtypid,NULL),'start',s.seqstart,'increment',s.seqincrement,'min',s.seqmin,'max',s.seqmax,'cache',s.seqcache,'cycle',s.seqcycle,'ownedBy',ARRAY(SELECT rn.nspname||'.'||rc.relname||'.'||a.attname FROM pg_depend d JOIN pg_class rc ON rc.oid=d.refobjid JOIN pg_namespace rn ON rn.oid=rc.relnamespace JOIN pg_attribute a ON a.attrelid=rc.oid AND a.attnum=d.refobjsubid WHERE d.objid=c.oid AND d.classid='pg_class'::regclass AND d.deptype IN ('a','i') ORDER BY 1))::text definition FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('auth','public')),
"effectiveSchemaGrants" AS (SELECT n.nspname||':'||role||':'||privilege id,n.nspname schema,role,privilege,has_schema_privilege(role,n.oid,privilege) allowed FROM pg_namespace n CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) role CROSS JOIN unnest(ARRAY['USAGE','CREATE']) privilege WHERE n.nspname IN ('auth','public')),
"effectiveSequenceGrants" AS (SELECT n.nspname||'.'||c.relname||':'||role||':'||privilege id,n.nspname||'.'||c.relname sequence,role,privilege,has_sequence_privilege(role,c.oid,privilege) allowed FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) role CROSS JOIN unnest(ARRAY['USAGE','SELECT','UPDATE']) privilege WHERE n.nspname IN ('auth','public') AND c.relkind='S'),
"unsupportedObjects" AS (SELECT 'relation:'||n.nspname||'.'||c.relname id,'view/materialized/foreign/partitioned relation'::text class FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('auth','public') AND (c.relkind IN ('v','m','f','p') OR c.relispartition) UNION ALL SELECT 'type:'||n.nspname||'.'||t.typname,'range/multirange/standalone composite type' FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace LEFT JOIN pg_class c ON c.oid=t.typrelid WHERE n.nspname IN ('auth','public') AND (t.typtype IN ('r','m') OR c.relkind='c') UNION ALL SELECT 'rule:'||r.id||':'||w.rulename,'custom rewrite rule' FROM relids r JOIN pg_rewrite w ON w.ev_class=r.oid WHERE w.rulename<>'_RETURN' UNION ALL SELECT 'routine:'||p.oid::regprocedure::text,'aggregate/window routine' FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('auth','public') AND p.prokind IN ('a','w')),
"schemas" AS (SELECT n.nspname id,pg_get_userbyid(n.nspowner) owner,n.nspacl::text acl FROM pg_namespace n WHERE n.nspname IN ('auth','public')),
"relations" AS (SELECT n.nspname||'.'||c.relname id,n.nspname schema,c.relname name,pg_get_userbyid(c.relowner) owner,c.relrowsecurity rls,c.relforcerowsecurity "forceRls",c.relacl::text acl,c.relkind::text kind FROM rel c JOIN pg_namespace n ON n.oid=c.relnamespace),
"columns" AS (SELECT r.id||'.'||a.attname id,r.id relation,a.attname name,a.attnum::int position,format_type(a.atttypid,a.atttypmod) type,a.attnotnull "notNull",pg_get_expr(d.adbin,d.adrelid) "default",a.attidentity::text identity,a.attgenerated::text generated,a.attacl::text acl FROM relids r JOIN pg_attribute a ON a.attrelid=r.oid LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped),
"constraints" AS (SELECT r.id||':'||c.conname id,r.id relation,c.conname name,c.convalidated validated,pg_get_constraintdef(c.oid,false) definition FROM relids r JOIN pg_constraint c ON c.conrelid=r.oid),
"indexes" AS (SELECT r.id||':'||c.relname id,r.id relation,pg_get_indexdef(i.indexrelid) definition,i.indisvalid valid,i.indisready ready,i.indislive live,i.indisunique "unique",i.indisprimary "primary" FROM relids r JOIN pg_index i ON i.indrelid=r.oid JOIN pg_class c ON c.oid=i.indexrelid),
"triggers" AS (SELECT r.id||':'||t.tgname id,r.id relation,t.tgname name,pg_get_triggerdef(t.oid,false) definition,t.tgenabled::text enabled,t.tgisinternal internal FROM relids r JOIN pg_trigger t ON t.tgrelid=r.oid),
"policies" AS (SELECT r.id||':'||p.polname id,r.id relation,p.polname name,p.polcmd::text command,p.polpermissive permissive,pg_get_expr(p.polqual,p.polrelid) "using",pg_get_expr(p.polwithcheck,p.polrelid) "check",ARRAY(SELECT CASE WHEN roleid=0 THEN 'public' ELSE pg_get_userbyid(roleid)::text END FROM unnest(p.polroles) roleid ORDER BY 1) roles FROM relids r JOIN pg_policy p ON p.polrelid=r.oid),
"functions" AS (SELECT p.oid::regprocedure::text id,pg_get_userbyid(p.proowner) owner,p.prosecdef definer,p.proconfig config,p.proacl::text acl,pg_get_functiondef(p.oid) definition FROM funcs p),
"effectiveTableGrants" AS (SELECT r.id||':'||role||':'||privilege id,r.id relation,role,privilege,has_table_privilege(role,r.oid,privilege) allowed FROM relids r CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) role CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) privilege),
"effectiveColumnGrants" AS (SELECT r.id||'.'||a.attname||':'||role||':'||privilege id,r.id||'.'||a.attname "column",role,privilege,has_column_privilege(role,r.oid,a.attnum,privilege) allowed FROM relids r JOIN pg_attribute a ON a.attrelid=r.oid CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) role CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','REFERENCES']) privilege WHERE a.attnum>0 AND NOT a.attisdropped),
"effectiveFunctionGrants" AS (SELECT p.oid::regprocedure::text||':'||role id,p.oid::regprocedure::text signature,role,has_function_privilege(role,p.oid,'EXECUTE') allowed FROM funcs p CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) role),
"roleMemberships" AS (SELECT r.rolname||':'||p.rolname||':'||pg_get_userbyid(m.grantor) id,r.rolname role,p.rolname "memberOf",pg_get_userbyid(m.grantor) grantor,m.admin_option admin,m.inherit_option inherit,m.set_option "set" FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.member JOIN pg_roles p ON p.oid=m.roleid),
"roles" AS (SELECT rolname id,rolsuper superuser,rolinherit inherit,rolcreaterole "createRole",rolcreatedb "createDb",rolcanlogin login,rolreplication replication,rolbypassrls "bypassRls",rolconfig config FROM pg_roles),
"defaultPrivileges" AS (SELECT pg_get_userbyid(d.defaclrole)||':'||coalesce(n.nspname,'*')||':'||d.defaclobjtype::text id,pg_get_userbyid(d.defaclrole) owner,n.nspname schema,d.defaclobjtype::text type,d.defaclacl::text acl FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname IN ('auth','public') OR d.defaclnamespace=0),
"authMigrationLedger" AS (SELECT version::text id FROM auth.schema_migrations)
SELECT jsonb_build_object('format','calcumint-full-catalog-v1','scope','{"schemas": ["auth", "public"], "publicTables": ["admin_alerts", "ai_usage_events", "api_usage_events", "batch_calculation_jobs", "batch_request_receipts", "billing_account_fences", "billing_atomic_completions", "billing_customers", "billing_webhook_events", "business_api_keys", "business_projects", "business_webhook_endpoints", "calculation_history", "calculation_projects", "calculator_bulk_jobs", "calculator_catalog_admin", "calculator_qa_checks", "calculator_review_events", "calculator_source_evidence", "client_workspaces", "custom_calculator_runs", "custom_calculator_versions", "custom_calculators", "embed_configs", "embed_events", "embed_lead_receipts", "embed_leads", "favorites", "lead_consents", "organization_audit_log", "organization_invitations", "organization_members", "organizations", "platform_admins", "profiles", "saved_scenarios", "share_links", "shared_calculations", "subscriptions", "user_preferences", "webhook_deliveries"], "authTables": ["audit_log_entries", "custom_oauth_providers", "flow_state", "identities", "instances", "mfa_amr_claims", "mfa_challenges", "mfa_factors", "mfa_recovery_code_sets", "mfa_recovery_codes", "oauth_authorizations", "oauth_client_states", "oauth_clients", "oauth_consents", "one_time_tokens", "refresh_tokens", "saml_providers", "saml_relay_states", "schema_migrations", "scim_tokens", "scim_users", "sessions", "sso_domains", "sso_providers", "users", "webauthn_challenges", "webauthn_credentials"], "migrationFiles": ["001_b3_accounts.sql", "002_b4_billing.sql", "003_b5_business.sql", "004_b6_builder.sql", "005_b7_delivery.sql", "006_b8_api_automation.sql", "007_b9_ai.sql", "008_b10_admin_factory.sql", "008b_b10_alert_automation.sql", "009_country_preferences.sql", "010_b7_pro_workspace.sql", "011_b8_free_save_quotas.sql", "012_production_fk_indexes.sql", "013_production_rpc_privilege_hardening_v2.sql", "014_production_entitlement_rpc_sync.sql", "016_final_certification_evidence_gate.sql", "017_regulatory_rule_pack_evidence.sql", "018_harden_rule_pack_required_metadata.sql", "019_authoritative_lifecycle_enforcement.sql", "020_post_certification_revalidation.sql", "021_require_rule_pack_provenance.sql", "022_harden_reviewer_waiver_authority.sql", "023_structured_source_evidence.sql", "024_reviewer_assignment_authority.sql", "025_derived_source_count_authority.sql", "026_publication_manifest_authority.sql", "027_publication_trigger_privilege_hardening.sql", "028_source_evidence_reviewer_index.sql", "029_account_rls_auth_initplan.sql", "030_billing_ai_rls_auth_initplan.sql", "031_admin_identity_rls_auth_initplan.sql", "032_atomic_reviewer_qa_audit.sql", "032_business_builder_rls_auth_initplan.sql", "033_atomic_reviewer_assignment_audit.sql", "033_pro_workspace_rls_auth_initplan.sql", "034_atomic_lifecycle_transition_audit.sql", "034_billing_webhook_event_privileges.sql", "035_atomic_catalog_creation.sql", "035_split_overlapping_write_policies.sql", "036_consolidate_ai_usage_read_policy.sql", "037_builder_publish_business_entitlement.sql", "038_client_account_billing_privileges.sql"], "roles": ["anon", "authenticated", "service_role"]}'::jsonb,'server',jsonb_build_object('major',current_setting('server_version_num')::int/10000),'sections',jsonb_build_object(
'types',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "types" x),
'sequences',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "sequences" x),
'effectiveSchemaGrants',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "effectiveSchemaGrants" x),
'effectiveSequenceGrants',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "effectiveSequenceGrants" x),
'unsupportedObjects',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "unsupportedObjects" x),
'schemas',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "schemas" x),
'relations',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "relations" x),
'columns',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "columns" x),
'constraints',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "constraints" x),
'indexes',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "indexes" x),
'triggers',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "triggers" x),
'policies',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "policies" x),
'functions',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "functions" x),
'effectiveTableGrants',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "effectiveTableGrants" x),
'effectiveColumnGrants',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "effectiveColumnGrants" x),
'effectiveFunctionGrants',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "effectiveFunctionGrants" x),
'roleMemberships',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "roleMemberships" x),
'roles',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "roles" x),
'defaultPrivileges',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "defaultPrivileges" x),
'authMigrationLedger',(SELECT jsonb_build_object('status','COMPLETE','count',count(*),'rows',coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)) FROM "authMigrationLedger" x),
'migrationLedger',jsonb_build_object('status','UNKNOWN','count',0,'rows','[]'::jsonb),
'effectLedger',jsonb_build_object('status','UNKNOWN','count',0,'rows','[]'::jsonb)));
COMMIT;
